package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen0Test {

















    @Test
    public void testCreateNumber_SuffixL() throws NumberFormatException {
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(Long.valueOf(-123L), NumberUtils.createNumber("-123l"));
        // Too big for long -> BigInteger
        String bigNum = "9223372036854775808"; // Long.MAX_VALUE + 1
        assertEquals(new BigInteger(bigNum), NumberUtils.createNumber(bigNum + "L"));
    }
















}

