public class NumberUtils_createNumber_TriageGen0Test {

































    @Test
    public void testCreateNumber_LargeFloatOverflow() throws NumberFormatException {
        // A value that is too large for float, should fall through to Double
        String huge = "1e40f"; 
        // If createFloat(huge) returns Infinity, the code moves to Double
        Number result = NumberUtils.createNumber(huge);
